    s.compare_region_intervals(iv,[{"name":"p","left":"A","right":"B"}])
except ValueError as e:
    print("overflow delta -> ValueError:", e)

# touching intervals lower_delta exactly 0.0 (not -0.0)
def row2(region, lo, hi, c):
    return {"region":region,"element":"e","window_count":1,"count":1,
            "center":c,"uncertainty":(hi-lo)/2,"lower":[lo],"upper":[hi]}
iv2={"schema":"climate-grid/rr-interval-v1","years":[2000],"reference":"r",
     "baseline":"b","scenarios":["s"],"elements":["e"],
     "windows":[{"name":"w","start":"2000-01-01","end":"2000-01-02"}],
     "regions":["A","B"],"factors":[1],"data":[row2("A",0.0,2.0,1.0),row2("B",2.0,4.0,3.0)]}
o=s.compare_region_intervals(iv2,[{"name":"p","left":"A","right":"B"}])
r=o["data"][0]
assert r["lower_delta"]==0.0 and str(r["lower_delta"])!="-0.0"
assert r["overlap"] is True
